@pushOnce('styles', 'crm-student-styles')
<style>
.crm-saved-searches{display:flex;flex-wrap:wrap;gap:12px}.crm-saved-search{display:flex;flex-wrap:wrap;gap:6px;min-width:0;border:1px solid var(--admin-line);border-radius:12px;padding:6px}.crm-saved-search>a{overflow-wrap:anywhere;white-space:normal}
.crm-advanced-filters{grid-column:1/-1;min-width:0;border-top:1px solid var(--admin-line);padding-top:12px}.crm-advanced-filters summary{cursor:pointer;min-height:44px;display:flex;align-items:center;font-weight:700;color:var(--admin-ink)}.crm-advanced-filters summary::before{content:'+';margin-right:10px}.crm-advanced-filters[open] summary::before{content:'−'}.crm-advanced-filters .crm-form-grid{padding:8px 0}.crm-advanced-filters summary:focus-visible{outline:3px solid var(--admin-primary);outline-offset:3px}
.crm-workspace [hidden]{display:none!important}
.crm-workspace{display:grid;gap:20px;min-width:0}.crm-workspace .page-head{margin-bottom:0}.crm-stages{display:flex;flex-wrap:wrap;gap:10px}.crm-stages [aria-current=page]{border-color:var(--admin-primary);background:var(--admin-primary-soft);color:var(--admin-primary-dark)}.crm-workspace .button{min-height:44px}.crm-filters{display:grid;grid-template-columns:minmax(200px,2fr) repeat(3,minmax(120px,1fr)) auto;align-items:end;gap:12px;padding:20px}.crm-filters label,.crm-form-grid label{display:grid;gap:8px;min-width:0;font-size:13px}.crm-filters .input,.crm-filters .select,.crm-form-grid .input,.crm-form-grid .select{width:100%;min-width:0;font-size:14px}.crm-student-list{overflow:hidden}.crm-student-row{display:grid;grid-template-columns:minmax(160px,1.3fr) minmax(170px,1.2fr) minmax(140px,1fr) auto;align-items:center;gap:16px;padding:20px;border-bottom:1px solid var(--admin-line)}.crm-student-row>div{min-width:0;overflow-wrap:anywhere}.crm-student-row p{margin:4px 0}.crm-profile-form{padding:24px}.crm-profile-form fieldset{min-width:0;margin:0 0 24px;padding:20px;border:1px solid var(--admin-line);border-radius:12px}.crm-profile-form legend{padding:0 8px;font-size:15px;font-weight:700;color:var(--admin-ink)}.crm-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.crm-help{color:var(--admin-muted);font-size:13px;line-height:1.7}.crm-form-footer{display:flex;align-items:center;justify-content:space-between;gap:20px}.crm-form-footer p{margin:0;max-width:55ch}.crm-history{padding:24px;overflow-wrap:anywhere}.crm-history h2{margin:0 0 16px;font-size:17px}.crm-history article{padding:14px 0;border-top:1px solid var(--admin-line)}.crm-history p,.crm-history time{margin:4px 0;font-size:13px;color:var(--admin-muted)}.crm-error{color:var(--admin-primary-dark);font-size:12px}.crm-workspace :is(a,button,input,select):focus-visible{outline:3px solid var(--admin-primary);outline-offset:3px}.crm-workspace .empty p{max-width:65ch;line-height:1.7}.crm-workspace h1{overflow-wrap:anywhere}
@media(max-width:1200px){.crm-filters{grid-template-columns:repeat(2,minmax(0,1fr))}.crm-student-row{grid-template-columns:repeat(2,minmax(0,1fr))}.crm-student-row>.button{justify-self:start}}
@media(max-width:600px){.crm-filters,.crm-form-grid,.crm-student-row{grid-template-columns:minmax(0,1fr)}.crm-profile-form,.crm-history{padding:16px}.crm-profile-form fieldset{padding:14px}.crm-filters{padding:16px}.crm-form-footer{align-items:stretch;flex-direction:column}.crm-workspace .page-head{align-items:start;flex-direction:column}.crm-workspace .page-head p{text-align:left}.crm-stages .button{flex:1 1 130px}}
</style>
@endPushOnce
